insert into public.knowledge_base(title,question_examples,approved_answer,category_code,tags,status,source_kind,source_ref,approved_at)
select e.title,e.question_examples,e.approved_answer,e.category_code,e.tags,'approved','admin','support-training-v2',now()
from entries e
where not exists(select 1 from public.knowledge_base kb where kb.title=e.title and kb.status='approved');

with rules(rule_name,instruction,priority) as (
values
('Prefer exact live workflow guidance','When a customer asks how to perform an action, explain the live customer-facing route or control from approved knowledge. Do not substitute a hypothetical workflow or an admin-only process.',900),
('Separate status explanation from promises','You may explain what a status generally means, but do not promise when a case will change status or guarantee an outcome unless the customer account already records it.',880),
('Never request authentication secrets','Never ask a customer for a password, one-time security code, recovery secret, API key or other authentication credential in support chat.',1000),
('Financial actions require verified live capability','Do not claim a payout, refund, wallet spend, payment, checkout or balance adjustment has occurred unless the live system provides that verified state. Route case-specific financial problems to human support.',990),
('Use human handoff for logistics disputes','Driver problems, disputed missed pickups, disputed pickup fees and other case-specific logistics disputes require human review.',930)
)
insert into public.ai_behavior_rules(rule_name,instruction,priority,status,approved_at)
select r.rule_name,r.instruction,r.priority,'approved',now()
from rules r
where not exists(select 1 from public.ai_behavior_rules x where x.rule_name=r.rule_name);
